// keyset page; the cursor stays opaque to callers
struct Page { std::vector<Row> rows; std::string next_token; };
Page fetch(std::string_view token, int page_size) {
  auto pos = decode_base64url(token);                 // (created_at, id) or start
  auto rs = conn.exec_params(
      "SELECT created_at, id FROM items "
      "WHERE (created_at, id) < ($1, $2) "
      "ORDER BY created_at DESC, id DESC LIMIT $3",
      {pos.ts, pos.id, std::to_string(page_size + 1)});
  return assemble(rs, page_size);                     // next_token empty at the end
}

auto range = client.ListBooks(request);   // request.page_token carried across pages
for (auto const& book : range) {          // StreamRange<StatusOr<Book>>
  if (!book) break;                       // a non-OK status terminates the range
  consume(*book);
}

